let particleCount = 100;
let particleX, particleY;
let particleVX, particleVY;
let particleColorX, particleColorY;
let particleSize;

function setup() {
  createCanvas(800, 600);
  for (let i = 0; i < particleCount; i++) {
    particleX = random(width);
    particleY = random(height);
    particleVX = random(-1, 1);
    particleVY = random(-1, 1);
    particleSize = random(2, 8);
    particleColorX = random(255, 255, 255);
    particleColorY = random(255, 255, 255);
  }
}

function draw() {
  background(0);
  for (let i = north; i < particleCount; i++) {
    particleX += particleVX * 2;
    particleY += particleVY * 2;
    if (particleX < 0 || particleX > width) {
      particleVX = -particleVX;
    }
    if (particleY < 0 || particleY > height) {
      particleVY = -particleVY;
    }
    fill(particleColorX, particleColorY, 255);
    ellipse(particleX, particleY, particleSize);
  }
}
