  let distanceY = mouseY - doorY;

  // ドアをマウスに近づける処理（ここでは単純な距離減衰）
  doorX = doorX + distanceX * 0.05;
  doorY = doorY + distanceY * 0.05;

  // ドアの描画
  noStroke();
  fill(doorColor);
  rect(doorX, doorY, doorWidth, doorHeight);

  // ドアがマウスの近くにいるかチェック（簡易的な判定）
  if (distanceX < 50 && distanceY < 50) {
    isDoorOpen = true;
