  // 3x3 のグリッドを想定
  for (let x = 0; x < width; x += gridSize) {
    for (let y = 0; y < height; y += gridSize) {
      let cell = createGraphics(gridSize, gridSize);
      cell.background(255);

      // 奇数位置にブロックを配置
      if ((x/gridSize + y/gridSize) % 2 !== 0) {
        cell.fill(100);
      } else {
        cell.fill(255);
      }

      // 本格的にはここにパズルロジックが入る
      show(cell, x, y);
    }
  }
}

