    let r = random(255);
    let g = random(255);
    let b = random(255);
    let color = [r, g, b];

    // テントンを生成
    for (let i = 0; i < numDots; i++) {
      dotX = random(width);
      dotY = random(height);

      // 線の色をランダムに設定
      stroke(colorBranch(i));
      strokeWeight(1);

      // マウスの位置に基づいて、点に小さな変化を与える
      let dist = dist(mouseX, mouseY, dotX, dotY);
      if (dist < 100) {
        // マウスに近い点に少し明るい色を適用
        let speed = map(100 - dist, 0, 100, 0, 1);
        stroke(colorBranch(i, speed));
        strokeWeight(2);
      } else {
        stroke(colorBranch(i));
        strokeWeight(1);
      }
    }
  } else {
    // マウスが押されていない場合、点線を消す（または固定する）
  }
}

// ランダムな色を生成するヘルパー関数
function colorBranch(index, speed) {
  let r = random(255);
  let g = random(255);
  let b = random(255);

  // 速度に基づいて色を微調整
  if (speed > 0.5) {
    r = 255;
    g = 255 - speed;
  } else {
    g = 255;
    b = 255 - speed;
  }

  return [r, g, b];
}
