  background(240);

  if (isGameOver) {
    fill(255, 0, 0);
    textSize(32);
    textAlign(CENTER, CENTER);
    text("ゲームオーバー", width / 2, height / 2);
    return;
  }

  // ゲームエリアの描画
  fill(// 任意の色
    255, 255, 240
  );
  rect(0, 0, width, height);
  fill(0, 255, 0);
  rect(gameAreaX, gameAreaY, width - gameAreaX, height - gameAreaY);

  // ボールの描画
  fill(255, 0, 0);
  ellipse(ballX, ballY, ballRadius, ballRadius);

  // ボールの移動
  ballX = ballX + ballVX;
  ballY = ballY + ballVY;

  // 画面の端で跳ね返す
  if (ballX > width) {
    ballX = width;
    ballVX = -ballVX * bounceFactor;
  } else if (ballX < 0) {
    ballX = 0;
    ballVX = -ballVX * bounceFactor;
  } else if (ballY > height) {
    ballY = height;
    ballVY = -ballVY * bounceFactor;
  } else if (ballY < 0) {
    ballY = 0;
    ballVY = -ballVY * bounceFactor;
  }

  // アタシが触った場合
  if (dist(ballX, ballY, width / 2) < ballRadius) {
    isGameOver = true;
  }
}
