let wave = 0;
let waveSpeed = 0.1;
let numCircles = 30;
let circleRadius = 15;
let numColors = 5;

function setup() {
  createCanvas(600, 400);
}

function draw() {
  background(240, 248, 255); // パステルブルー
  wave = wave + waveSpeed;

  for (let i = 0; i < numCircles; i++) {
    let x = (i * 20) + (width / 2) + sin(x * 0.5 + wave * 0.5) * 20;
    let y = height / 2 + cos(i * 0.5 + wave * 0.3) * 10;

    let color;
    if (it % numColors === 0) {
      color = color(255, 165, 0, 150); // オレンジ
    } else if (it % numColors === 1) {
      color = color(255, 255, 192, 150); // ホワイト
    } else if (it % numColors === 2) {
      color = color(173, 216, 230, 150); // ライトスカイブルー
    } else if (it % numColors === 3) {
      color = color(255, 184, 11, 150); // イエロー
    } else {
      color = color(255, 105, 180, 150); // マゼンタ
    }

    fill(color);
    noStroke();
    ellipse(x, y, circleRadius, circleRadius);
  }
}
